from collections import deque
from datetime import timedelta
class LegacyLimiter:
    def __init__(self, limit, window_s):
        self.limit, self.window, self._hits = limit, timedelta(seconds=window_s), deque()
    def allow(self, ts):
        while self._hits and self._hits[0] < ts - self.window:   # closed interval [t-w, t]
