class SlidingWindowLimiter:
    def __init__(self, limit, window_s):
        self.limit = limit
        self.window = timedelta(seconds=window_s)
        self._hits = deque()

    def allow(self, ts=None):
        ts = ts or _now()
        cutoff = ts - self.window
        while self._hits and self._hits[0] <= cutoff:
