from ratelimit import SlidingWindowLimiter
T0 = datetime(2026, 1, 1, tzinfo=timezone.utc)
def s(x): return T0 + timedelta(seconds=x)

def test_allows_up_to_limit():
    l = SlidingWindowLimiter(3, 10)
    assert [l.allow(s(0)), l.allow(s(1)), l.allow(s(2))] == [True, True, True]

def test_limit_exclusive():
    # third request is over the limit of 3
    l = SlidingWindowLimiter(3, 10)
    l.allow(s(0)); l.allow(s(1))
    assert l.allow(s(2)) is False

def test_boundary_reopens():
    l = SlidingWindowLimiter(1, 10)
    assert l.allow(s(0)) is True
    assert l.allow(s(10)) is True   # exactly window_s later: the old hit is outside (t-w, t]

def test_default_clock():
    l = SlidingWindowLimiter(2, 1)
    assert l.allow() is True

